    Bug 1915157 - Port bug 1914987: Indicate ARM64 on "About Thunderbird" popup. r=mkmelin

    Differential Revision: https://phabricator.services.mozilla.com/D221270

diff --git a/mail/base/content/aboutDialog.js b/mail/base/content/aboutDialog.js
index 8549993af8a..238b8be7c12 100644
--- a/mail/base/content/aboutDialog.js
+++ b/mail/base/content/aboutDialog.js
@@ -52,15 +52,28 @@ function onLoad(event) {
   }

   // Include the build ID and display warning if this is an "a#" (nightly or aurora) build
-  let versionId = "aboutDialog-version";
+  const versionIdMap = new Map([
+    ["base", "aboutDialog-version"],
+    ["base-nightly", "aboutDialog-version-nightly"],
+    ["base-arch", "aboutdialog-version-arch"],
+    ["base-arch-nightly", "aboutdialog-version-arch-nightly"],
+  ]);
+  let versionIdKey = "base";
   const versionAttributes = {
     version: AppConstants.MOZ_APP_VERSION_DISPLAY,
-    bits: Services.appinfo.is64Bit ? 64 : 32,
   };

+  const arch = Services.sysinfo.get("arch");
+  if (["x86", "x86-64"].includes(arch)) {
+    versionAttributes.bits = Services.appinfo.is64Bit ? 64 : 32;
+  } else {
+    versionIdKey += "-arch";
+    versionAttributes.arch = arch;
+  }
+
   const version = Services.appinfo.version;
   if (/a\d+$/.test(version)) {
-    versionId = "aboutDialog-version-nightly";
+    versionIdKey += "-nightly";
     const buildID = Services.appinfo.appBuildID;
     const year = buildID.slice(0, 4);
     const month = buildID.slice(4, 6);
@@ -74,7 +87,11 @@ function onLoad(event) {
   // Use Fluent arguments for append version and the architecture of the build
   const versionField = document.getElementById("version");

-  document.l10n.setAttributes(versionField, versionId, versionAttributes);
+  document.l10n.setAttributes(
+    versionField,
+    versionIdMap.get(versionIdKey),
+    versionAttributes
+  );

   if (!AppConstants.NIGHTLY_BUILD) {
     // Show a release notes link if we have a URL.
diff --git a/mail/locales/en-US/messenger/aboutDialog.ftl b/mail/locales/en-US/messenger/aboutDialog.ftl
index e14777deee0..e33050648d6 100644
--- a/mail/locales/en-US/messenger/aboutDialog.ftl
+++ b/mail/locales/en-US/messenger/aboutDialog.ftl
@@ -59,6 +59,19 @@ aboutDialog-version = { $version } ({ $bits }-bit)
 #   $bits (Number): bits of the architecture (32 or 64)
 aboutDialog-version-nightly = { $version } ({ $isodate }) ({ $bits }-bit)

+# Example of resulting string: 131.0a1 (aarch64)
+# Variables:
+#   $version (String): version of Thunderbird, e.g. 66.0.1
+#   $arch (String): name of the architecture (arm, aarch64, etc.)
+aboutdialog-version-arch = { $version } ({ $arch })
+
+# Example of resulting string: 131.0a1 (2024-08-27) (aarch64)
+# Variables:
+#   $version (String): version of Thunderbird for Daily builds, e.g. 66.0a1
+#   $isodate (String): date in ISO format, e.g. 2019-01-16
+#   $arch (String): name of the architecture (arm, aarch64, etc.)
+aboutdialog-version-arch-nightly = { $version } ({ $isodate }) ({ $arch })
+
 aboutdialog-update-checking-failed = Failed to check for updates.

